INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-white-house-oversight-warning', 'white-house-counsel-scharf-letter-warns-garcia-oversight-probes-blatant-criminality', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'White House counsel warns incoming Oversight Democrats that their planned probes could cross into "criminality"', 'A letter from Will Scharf to Rep. Robert Garcia, reported on Wednesday, Nov. 11, opens an early fight over the investigations Democrats plan once they take the House majority in January.', 'White House counsel Will Scharf has warned Rep. Robert Garcia, the top Democrat on the House Oversight Committee, that some of the investigations Democrats are planning could amount to crimes, the Associated Press and Forbes reported on Wednesday, Nov. 11. The letter is dated Monday, Nov. 9, and was first reported by Punchbowl News.

## What the letter says

Scharf wrote that Congress may only investigate for a legislative purpose and argued that statements from Garcia and other Democrats show an intent to go beyond that, according to Forbes. He wrote that threats or processes meant to deter officials from public service or to frighten them "may cross the line into blatant criminality," the AP reported, and said the administration "will not be extorted," according to Forbes.

## Garcia''s answer

Garcia is expected to chair the Oversight Committee when the Democratic-controlled House is seated in January. Before the midterms he told Trump officials to "lawyer up." On Wednesday he said President Trump "is clearly hiding something" and that Democrats would not be intimidated, describing Congress as a coequal branch of government, the AP reported.

## What Democrats plan to examine

The AP listed several areas Democrats have discussed: how the president and his family have grown wealthier since he returned to office, which the White House denies involves wrongdoing; the handling of the Jeffrey Epstein investigation; Immigration and Customs Enforcement operations; the White House ballroom and other construction; Trump family mineral deals; and cryptocurrency dealings involving special envoy Steve Witkoff.

## Other reactions

Rep. James Comer, R-Ky., the current Oversight chairman, said he had not read the letter and called Garcia''s "lawyer up" remarks in bad taste, the AP reported. Attorney General Todd Blanche earlier said on CNN there "could be" a crime if Democratic rhetoric turned threatening, then struck a softer tone, saying the Justice Department would keep working with Congress through subpoenas and letters, according to the AP. Rep. Mark DeSaulnier, D-Calif., expected to lead the House Ethics Committee, said he would not back down. Princeton law professor Deborah Pearlstein called the letter "ham-fisted" intimidation, Forbes reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/1/13/Flickr_-_USCapitol_-_National_Statuary_Hall_-_U.S._Capitol.jpg', 'National Statuary Hall, the former House chamber in the U.S. Capitol (file). Photo: Architect of the Capitol via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 9, 1, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
