INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-schumer-leadership', 'sanders-slotkin-wont-back-schumer-senate-democratic-leader-van-hollen-weighs-run', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Sanders and Slotkin say they will not back Chuck Schumer to lead the new Senate Democratic majority', 'The challenge, made public on Tuesday, Nov. 10, comes as Chris Van Hollen calls colleagues about a possible run. Senate Democrats are expected to pick their leaders later this month or in early December.', 'Sen. Bernie Sanders, I-Vt., said on Tuesday, Nov. 10, that he will not support Sen. Chuck Schumer, D-N.Y., for another term as Democratic leader when the new Congress convenes in January, the Associated Press reported via PBS NewsHour. Sanders spoke at a Capitol news conference alongside Sen. Elissa Slotkin, D-Mich., and said "the time is now for change."

## Slotkin''s condition

Slotkin said she is not seeking the job, but that she is a "no" until a candidate presents a full plan for how the majority would govern, including its first 100 days, according to the AP and ANI. Several incoming Democratic senators have also called for new leadership, the AP reported.

## Schumer and Van Hollen

Schumer, 75, has shown few signs of stepping aside and said he was confident he would be elected, the AP reported. Sen. Kirsten Gillibrand, who chairs the Democratic Senatorial Campaign Committee, defended his record. The AP noted that Schumer recruited Sherrod Brown in Ohio and Roy Cooper in North Carolina, but that his preferred candidates lost primaries in Michigan and Maine.

Sen. Chris Van Hollen, D-Md., who progressives including Michigan Sen.-elect Abdul El-Sayed have promoted, said he was "in the process right now of calling my colleagues," according to the AP. No formal challenger has declared, ANI reported.

## The timetable

The AP said Senate Democratic leadership elections are expected later this month, while ANI reported they are expected in early December. Democrats are projected to hold at least 54 Senate seats in the new Congress.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/9/9f/Flickr_-_USCapitol_-_Old_Senate_Chamber_(1).jpg', 'The Old Senate Chamber in the U.S. Capitol (file). Photo: Architect of the Capitol via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 8, 0, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
