INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-voa-appeals-ruling', 'appeals-court-voice-of-america-director-abramowitz-firing-illegal-kari-lake-pillard', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Appeals court rules Voice of America director Michael Abramowitz was removed illegally', 'A unanimous D.C. Circuit panel on Tuesday, Nov. 10, upheld an order that blocked the Trump administration from ousting him.', 'A three-judge panel of the U.S. Court of Appeals for the D.C. Circuit ruled unanimously on Tuesday, Nov. 10, that Trump administration officials, including Kari Lake, broke federal law when they tried to remove Voice of America director Michael Abramowitz in 2025, TheWrap and Law Commentary reported. Judge Cornelia Pillard wrote the opinion.

## Why the court ruled for him

A 2021 law requires approval from the International Broadcasting Advisory Board before the VOA director can be removed. President Trump had fired six of the board''s seven members, leaving it unable to approve the move, according to both reports. Law Commentary reported that the government conceded the removal broke the statute but argued Congress had no power to impose the limit. The panel rejected that argument, finding the president keeps enough control because he can dismiss board members. Pillard described the law as a "durable barrier" protecting VOA''s journalistic independence, TheWrap reported.

## Background

Abramowitz was told in July 2025 to accept a reassignment to North Carolina, declined, and was notified on Aug. 1, 2025, that he would be removed, Law Commentary reported. Judge Royce Lamberth blocked the removal, and the appeals ruling keeps that injunction in place. Abramowitz and about 1,300 other VOA employees were placed on leave after the president ordered the agency sharply reduced in March 2025, TheWrap reported. Separate lawsuits over the agency''s cuts are still pending, and Abramowitz welcomed the decision, according to Law Commentary.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:42400:42412/full/pct:25/0/default.jpg', 'The E. Barrett Prettyman Federal Courthouse, home of the U.S. Court of Appeals for the D.C. Circuit, Washington (file). Photo: Carol M. Highsmith / Library of Congress, no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 7, 0, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
