INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-veterans-day-arlington', 'trump-veterans-day-arlington-tomb-unknown-soldier-wreath-iran-va-claims', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump lays a wreath at the Tomb of the Unknown Soldier and praises troops in the Iran conflict on Veterans Day', 'The president spoke at Arlington National Cemetery on Wednesday, Nov. 11, the 108th anniversary of the World War I armistice.', 'President Trump laid a wreath at the Tomb of the Unknown Soldier and spoke at a Veterans Day ceremony at Arlington National Cemetery on Wednesday, Nov. 11, The Signal of Santa Clarita Valley reported.

## The speech

The president told veterans the country renders them "the highest salute," and recognized veterans of several eras, including 103-year-old World War II Army veteran Cpl. Wilbur "Jack" Myers, according to The Signal. He thanked service members involved in the conflict with Iran, which he called the world''s leading state sponsor of terror, and said Iran must never have a nuclear weapon. He also pointed to Department of Veterans Affairs efforts on the claims backlog and veteran homelessness.

## Who attended

First lady Melania Trump, Vice President JD Vance, VA Secretary Doug Collins, Secretary of War Pete Hegseth, Attorney General Todd Blanche and FBI Director Kash Patel were among those present, The Signal reported. Collins, who spoke before the president, said the VA has opened 47 new facilities since 2025.

## The proclamation

In a Veterans Day proclamation signed on Tuesday, Nov. 10, the White House said the VA processed a record 3.1 million disability claims this year and cut its claims backlog by more than 70 percent during the president''s second term. It also said nearly 52,000 homeless veterans were housed last year. Boston Daily has not independently verified those figures.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/a/a8/Tomb_guards_maintain_vigil_during_winter_storm_130306-A-ND255-014.jpg', 'Tomb guards of the 3rd U.S. Infantry Regiment at the Tomb of the Unknowns, Arlington National Cemetery, March 2013 (file). Photo: Sgt. Jose Torres Jr., U.S. Army, via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 6, 0, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261112-veterans-day-arlington-src1', 'bd-20261112-veterans-day-arlington', 'Trump honors veterans at Arlington National Cemetery', 'https://signalscv.com/2026/11/trump-honors-veterans-at-arlington-national-cemetery/', 'The Signal (Santa Clarita Valley)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-12T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-12. Editor to confirm.', 'newsroom-assistant', '2026-11-12T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261112-veterans-day-arlington-src2', 'bd-20261112-veterans-day-arlington', 'Veterans Day, 2026 (proclamation)', 'https://www.whitehouse.gov/presidential-actions/2026/11/veterans-day-2026/', 'The White House', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-12T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-12. Editor to confirm.', 'newsroom-assistant', '2026-11-12T10:45:00.000Z');
