INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-celtics-raptors', 'celtics-rally-from-22-down-beat-raptors-98-93-tatum-24-points-fifth-straight-win', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Celtics erase a 22-point deficit to beat the Raptors 98-93 and finish a 4-0 road trip', 'Jayson Tatum had 24 points and 8 assists in Toronto on Wednesday, Nov. 11, as Boston won its fifth straight game to improve to 10-2.', 'The Boston Celtics came back from 22 points down to beat the Toronto Raptors 98-93 at Scotiabank Arena on Wednesday, Nov. 11, extending their winning streak to five games and improving to 10-2, according to the Celtics and CBS Sports.

## How Boston came back

Toronto led 59-37 in the second quarter after making 10 3-pointers in the first quarter, which tied a franchise record for a quarter, the Celtics reported. Boston answered with a 16-0 run, with Tatum scoring the first 11 points of it, and took its first lead since the opening minutes midway through the third quarter. Tatum scored seven points late, including the go-ahead free throw with 25 seconds left, and Sam Hauser sealed the game with a steal.

## The numbers

Tatum finished with 24 points, 7 rebounds and 8 assists, although he shot 6 of 21 from the field, The Boston Globe reported. He made 10 of 12 free throws, according to the Celtics. Derrick White scored 19 and blocked four shots, and Neemias Queta added 11 points and a game-high 13 rebounds. Ja''Kobe Walter led Toronto with 17 points, CBS Sports reported. Paul George missed the game with an illness, while Toronto was without Kawhi Leonard and Scottie Barnes, the Globe reported.

## The trip

The win completed a 4-0 road trip with a plus-86 scoring margin, which the Celtics said is the best for a four-game road trip in franchise history.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/f/f9/President_John_F._Kennedy_Greets_the_Boston_Celtics.jpg', 'President John F. Kennedy greets the Boston Celtics in the Oval Office, Jan. 31, 1963 (file). Photo: Robert Knudsen, White House / John F. Kennedy Presidential Library, via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 5, 0, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
