INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-cy-young', 'cy-young-award-2026-cam-schlittler-yankees-jacob-misiorowski-brewers-unanimous', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Yankees'' Cam Schlittler and Brewers'' Jacob Misiorowski win the Cy Young Award unanimously', 'The awards, announced on Wednesday, Nov. 11, mark only the third year with two unanimous Cy Young winners. MVP announcements follow on Thursday, Nov. 12.', 'Yankees right-hander Cam Schlittler won the American League Cy Young Award and Brewers right-hander Jacob Misiorowski won the National League award on Wednesday, Nov. 11, both receiving all 30 first-place votes from the Baseball Writers'' Association of America, the Associated Press reported via the News Tribune. It is the third time both winners were unanimous, after 1968 and 2022.

## Schlittler

Schlittler went 14-6 with a 1.95 ERA in 33 starts and 239 strikeouts, the AP reported. That ERA was the American League''s lowest since 2022 and the third-lowest in Yankees history among qualified pitchers. He is the second Yankees pitcher in four seasons to win the award, after Gerrit Cole in 2023. Toronto''s Dylan Cease finished second and Cleveland''s Parker Messick third.

## Misiorowski

Misiorowski, 24, went 16-5 with a 1.80 ERA and 252 strikeouts, the AP reported. MLB.com said his ERA and strikeout total led all major league starters and that opponents hit .157 against him. He then went 2-0 in the World Series, which Milwaukee won 4-1 over Tampa Bay, including the clinching Game 5. Philadelphia''s Cristopher Sanchez was second and Atlanta''s Chris Sale third. He is the second Brewer to win the NL award, after Corbin Burnes in 2021.

## Also announced

Toronto''s Louis Varland and San Diego''s Mason Miller were named the Reliever of the Year winners, the AP reported. The Most Valuable Player awards are scheduled to be announced on Thursday, Nov. 12.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/6/66/Cy_Young_by_Conlon,_1911-crop.jpg', 'Cy Young, the pitcher the award is named for, warming up with the Cleveland Naps, circa 1911 (file). Photo: Charles M. Conlon via Wikimedia Commons, public domain in the U.S.', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 4, 0, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
