INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261112-patriots-injury-report', 'patriots-lions-munich-injury-report-henderson-davis-ben-brown-out-aj-brown-returns', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Patriots rule out three for Sunday''s game against the Lions in Munich as A.J. Brown returns to practice', 'TreVeyon Henderson, Carlton Davis III and Ben Brown will miss the Sunday, Nov. 15, game in Germany, according to Wednesday''s injury report. Drake Maye was a full participant.', 'The New England Patriots ruled out running back TreVeyon Henderson (illness), cornerback Carlton Davis III (knee) and guard-center Ben Brown (knee) for their game against the Detroit Lions in Munich on Sunday, Nov. 15, according to the team''s injury report from Wednesday, Nov. 11.

## Who practiced

Wide receiver A.J. Brown (ankle, knee) returned as a limited participant, as did tight end Hunter Henry, tackle Morgan Moses, safety Kevin Byard III, fullback Reggie Gilliam, guard Greg Van Roten and cornerback Charles Woods, the Patriots reported. Quarterback Drake Maye (right shoulder) was a full participant. Running back Rhamondre Stevenson (knee), tight end Cameron Latu, lineman Walter Rouse (concussion protocol) and safety Brenden Schooler did not practice.

For Detroit, quarterback Jared Goff and receiver Amon-Ra St. Brown were limited, while center Cade Mays and cornerback DJ Reed did not practice, according to the report. The Grey Manes reported that Lions coach Dan Campbell said Reed and Mays are unlikely to play.

## The setting

The Patriots are 5-4 after losing 45-27 to the Green Bay Packers on Sunday, Nov. 8. The game in Munich will be the NFL''s sixth regular-season game in Germany, Boston.com reported, noting that the previous two German games went to overtime and that no quarterback has thrown for 300 yards in one.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/9/98/U_S_Soldiers_at_Munich_Ravens_American_Football_Game_in_Nuremberg_(8499074).jpg', 'U.S. soldiers line the field before a Munich Ravens American football game in Nuremberg, Germany, June 2024 (file). Photo: Micah Welch, U.S. Army, via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-12.sql', 3, 0, 'newsroom-assistant', '2026-11-12T10:45:00.000Z', '2026-11-12T10:45:00.000Z');
